{
  "diagnosis": "Option selection failed to consistently prioritize the medication whose primary indication matches the diagnosed condition; it sometimes chose a drug that was safe but not indicated, or a less appropriate alternative, instead of the best-supported indication match.",
  "skills": [
    {
      "id": "indication_first",
      "text": "When choosing among options, first identify the option whose primary labeled indication directly matches the diagnosed condition; eliminate options that are safe but not indicated for that condition."
    },
    {
      "id": "best_supported_choice",
      "text": "If multiple options are safe, prefer the one with the strongest direct evidence or standard first-line role for the diagnosed condition rather than a secondary, adjunctive, or unrelated agent."
    },
    {
      "id": "avoid_safe_but_wrong",
      "text": "Do not select an option merely because it lacks a contraindication; safety is necessary but not sufficient, and the option must also treat the target condition."
    }
  ],
  "focus_terms": [
    "indicated",
    "first-line",
    "best-supported",
    "target condition",
    "safe but not indicated"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. First, match each option's primary labeled indication to the diagnosed condition and eliminate options that are safe but not indicated. Among remaining safe options, prefer the one with the strongest direct evidence or standard first-line role for that condition. Do not choose an option solely because it lacks a contraindication; it must also treat the target condition."
  }
}

{
  "diagnosis": "The option_selection module fails to prioritize the option that is specifically indicated for the patient's stated condition and documented safety profile, instead selecting an option that is either less supported or contraindicated by the patient's current medications or comorbidities.",
  "skills": [
    {
      "id": "indication_first",
      "text": "When selecting a medication, first identify the patient's primary diagnosis and any documented contraindications or interactions. Choose the option that is explicitly indicated for that diagnosis and has no documented safety concerns. If multiple options are indicated, prefer the one with the strongest guideline support or the one that is not already failing or contraindicated."
    },
    {
      "id": "avoid_contraindicated",
      "text": "Do not select an option that is contraindicated by the patient's current medications, comorbidities, or known allergies. For example, if the patient is already taking a medication that is not working or is causing side effects, avoid choosing the same medication again unless no alternative exists."
    },
    {
      "id": "prefer_specific_over_symptomatic",
      "text": "When choosing between a medication that treats the underlying condition and one that only provides symptomatic relief, prefer the disease-modifying or curative option unless the patient's condition or safety profile makes the symptomatic option more appropriate."
    }
  ],
  "focus_terms": [
    "indicated for",
    "contraindicated",
    "first-line",
    "guideline-recommended",
    "disease-modifying"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that is explicitly indicated for the patient's primary diagnosis and has no documented contraindications or interactions. If multiple options are indicated, prefer the one with the strongest guideline support or the one that is not already failing or contraindicated. Avoid selecting an option that is only symptomatic if a disease-modifying option is available and safe. Do not choose an option that is contraindicated by the patient's current medications, comorbidities, or known allergies."
  }
}

