    },
    {
      "id": "comorbidity_override",
      "text": "If a stated comorbidity or recent procedure alters the risk-benefit of otherwise indicated options, select the option that remains indicated while minimizing that specific risk; if all indicated options carry some risk, choose the one with the least severe or most manageable risk given the stated facts."
    },
    {
      "id": "avoid_unstated_assumptions",
      "text": "Do not assume a missing patient fact (e.g., allergy, renal function, pregnancy) is present or absent; base selection only on facts explicitly stated in the dialogue."
    }
  ],
  "focus_terms": [
    "patient-specific safety",
